const newsItems = $input.all()[0].json.items;
const originalInput = $node['Parse Input'].json.original_input;

const keyword = originalInput.keyword || '네이버';
const count = originalInput.count || newsItems.length;

const decodeEntities = (text) =>
  text
    .replace(/&quot;/g, '"')
    .replace(/&apos;/g, "'")
    .replace(/&lt;/g, "<")
    .replace(/&gt;/g, ">")
    .replace(/&amp;/g, "&");

let html = `요청하신 <strong>"${keyword}"</strong> 관련 기사를 찾아 보내드립니다.<br/><br/>`;

if (!newsItems || newsItems.length === 0) {
  html += `<p><strong>"${keyword}"</strong>에 대한 뉴스를 찾을 수 없습니다.</p>`;
  return [{ json: { body: html, search_query: keyword, count: 0 } }];
}

newsItems.forEach((item, index) => {
  let title = decodeEntities(item.title.replace(/<[^>]+>/gm, ''));
  const description = decodeEntities(item.description.replace(/<[^>]+>/gm, ''));
  const link = item.link;

  // title이 짤려있다면 description의 앞부분으로 보정
  if (title.endsWith('…')) {
    const firstSentence = description.split(/[.!?]\s/)[0];
    if (firstSentence && firstSentence.length > title.length) {
      title = firstSentence;
    }
  }

  html += `<strong>${index + 1}. <a href="${link}" target="_blank">${title}</a></strong><br/>`;
  html += `요약내용 : ${description}<br/><br/>`;
});

return [{ json: { body: html, search_query: keyword, count: count } }];

// MCP에서 받은 전체 입력 데이터 확인
const input = $input.first().json;
console.log('Complete input received:', JSON.stringify(input));

// 다양한 input 경로에서 전체 텍스트 추출
let fullText = '';
let count = 10;

// MCP에서 올 수 있는 다양한 형태의 입력 처리
if (input.body && input.body.input) {
  fullText = input.body.input;
} else if (input.input) {
  fullText = input.input;
} else if (input.query) {
  fullText = input.query;
} else if (input.message) {
  fullText = input.message;
} else if (input.text) {
  fullText = input.text;
} else if (typeof input === 'string') {
  fullText = input;
} else if (input.body && typeof input.body === 'string') {
  fullText = input.body;
} else {
  // 혹시 다른 필드에 있는지 확인
  const possibleFields = ['prompt', 'content', 'request', 'data'];
  for (const field of possibleFields) {
    if (input[field]) {
      fullText = input[field];
      break;
    }
  }
}

console.log('Extracted fullText:', fullText);

if (!fullText) {
  console.log('No text found in input, using default');
  fullText = '네이버';
}

// 이제 전체 텍스트에서 검색어와 개수 파싱
let search_query = fullText;

// 개수 추출 (다양한 패턴)
const countPatterns = [
  /(\d+)개/,
  /(\d+)건/,
  /top\s*(\d+)/i,
  /(\d+)\s*개/,
  /^(\d+)/
];

for (const pattern of countPatterns) {
  const match = fullText.match(pattern);
  if (match) {
    count = parseInt(match[1]);
    break;
  }
}

// 검색어 추출 (불필요한 단어들 제거)
search_query = fullText
  .replace(/\d+개.*?/g, '')
  .replace(/\d+건.*?/g, '')
  .replace(/top\s*\d+.*?/ig, '')
  .replace(/관련.*?기사/g, '')
  .replace(/기사.*?보내/g, '')
  .replace(/뉴스.*?보내/g, '')
  .replace(/크롤링.*?/g, '')
  .replace(/보내줘|해줘|가져와|검색|찾아/g, '')
  .replace(/관련|기사|뉴스/g, '')
  .trim();

// 빈 검색어 방지
if (!search_query) {
  search_query = '네이버';
}

console.log('Final parsed - search_query:', search_query, 'count:', count);

return [{
  json: {
    search_query: search_query,
    count: count,
    original_input: input,
    full_text: fullText
  }
}];

