const input = $input.first().json;

// query에 담긴 문자열을 JSON으로 파싱
let parsed = {};
if (typeof input.query === 'string') {
  try {
    parsed = JSON.parse(input.query);  // 문자열 → JSON 객체
  } catch (e) {
    throw new Error('query 내부 문자열 파싱 실패: ' + e.message);
  }
} else {
  parsed = input.query;  // 이미 파싱된 경우
}

// 개별 요소 추출
const keyword = parsed.query.input;
const count = parsed.query.count;
const toolName = parsed.tool.name;

// 예시 출력
return {
  keyword,
  count,
  toolName,
  original: parsed
};
